import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

// Formats a number to string with commas (e.g., 1000000 -> 1,000,000)
export const formatCurrency = (value: number): string => {
  if (isNaN(value)) return '0';
  return new Intl.NumberFormat('fa-IR').format(value);
};

// Parses a string with commas back to a number (e.g., "1,000,000" -> 1000000)
export const parseCurrency = (value: string): number => {
  // Remove non-numeric characters except for English and Persian digits if needed, 
  // but usually just removing commas is enough for standard inputs.
  const cleanValue = value.replace(/,/g, '').replace(/[^\d]/g, '');
  const num = parseInt(cleanValue, 10);
  return isNaN(num) ? 0 : num;
};

// Conversion Constants
// 1 Million Rahn = 30,000 Rent
export const RAHN_TO_RENT_RATE = 30000; 
export const RAHN_UNIT = 1000000;

// Converts Rahn to equivalent Rent
export const rahnToRent = (rahn: number): number => {
  return (rahn / RAHN_UNIT) * RAHN_TO_RENT_RATE;
};

// Converts Rent to equivalent Rahn
export const rentToRahn = (rent: number): number => {
  return (rent / RAHN_TO_RENT_RATE) * RAHN_UNIT;
};

// Calculates total value of a deal in terms of "Full Rahn"
export const calculateTotalRahnValue = (rahn: number, rent: number): number => {
  return rahn + rentToRahn(rent);
};

import React from 'react';
import { formatCurrency, parseCurrency } from '../utils/currency';

interface CurrencyInputProps {
  label: string;
  value: number;
  onChange: (value: number) => void;
  placeholder?: string;
  className?: string;
  disabled?: boolean;
}

const CurrencyInput: React.FC<CurrencyInputProps> = ({ 
  label, 
  value, 
  onChange, 
  placeholder = "0",
  className = "",
  disabled = false
}) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value;
    const numValue = parseCurrency(rawValue);
    onChange(numValue);
  };

  return (
    <div className={`flex flex-col gap-1 ${className}`}>
      <label className="text-sm font-medium text-slate-600">{label}</label>
      <div className="relative">
        <input
          type="text"
          inputMode="numeric"
          value={value === 0 ? '' : formatCurrency(value)}
          onChange={handleChange}
          disabled={disabled}
          placeholder={placeholder}
          className={`w-full p-3 pl-12 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all text-left dir-ltr font-mono text-lg
            ${disabled ? 'bg-slate-100 text-slate-400 border-slate-200' : 'bg-white border-slate-300 text-slate-800'}`}
        />
        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm pointer-events-none">
          تومان
        </span>
      </div>
    </div>
  );
};

export default CurrencyInput;

import React, { useState, useEffect } from 'react';
import CurrencyInput from './CurrencyInput';
import { calculateTotalRahnValue, formatCurrency, rahnToRent, RAHN_UNIT } from '../utils/currency';
import { Calculator } from 'lucide-react';

const BasicConversion: React.FC = () => {
  // State: We keep track of the "Full Rahn Value" (Total Value) and the "Selected Rahn"
  const [totalValue, setTotalValue] = useState<number>(1000000000); // Default 1 Billion
  const [mortgagePart, setMortgagePart] = useState<number>(500000000); // Default 500 Million
  const [rentPart, setRentPart] = useState<number>(0);

  // When Total Value or Mortgage Part changes, recalculate Rent
  useEffect(() => {
    // Ensure mortgage part doesn't exceed total value
    if (mortgagePart > totalValue) {
      setMortgagePart(totalValue);
      setRentPart(0);
    } else {
      const remainingForRent = totalValue - mortgagePart;
      setRentPart(rahnToRent(remainingForRent));
    }
  }, [totalValue, mortgagePart]);

  const handleSliderChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    // Slider returns percentage (0-100) or direct step value
    // Let's use steps of 1 Million for smoother UX on slider
    const val = Number(e.target.value);
    setMortgagePart(val);
  };

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 flex items-start gap-3">
        <Calculator className="w-6 h-6 text-blue-600 mt-1 flex-shrink-0" />
        <div>
          <h3 className="font-bold text-blue-800 text-lg mb-1">تبدیل رهن کامل به ترکیبی</h3>
          <p className="text-blue-600 text-sm leading-relaxed">
            مبلغ «رهن کامل» ملک را وارد کنید. سپس با تغییر نوار لغزنده، نسبت رهن و اجاره را تعیین کنید.
            مبنای محاسبه: هر ۱ میلیون تومان رهن = ۳۰ هزار تومان اجاره.
          </p>
        </div>
      </div>

      {/* Input Section */}
      <div className="grid gap-6">
        <CurrencyInput
          label="ارزش رهن کامل ملک (تومان)"
          value={totalValue}
          onChange={(val) => {
            setTotalValue(val);
            // Reset split to roughly 50% or keep ratio if needed, but keeping current amount valid is safer
            if (val < mortgagePart) setMortgagePart(val);
          }}
        />

        <div className="p-6 bg-white border border-slate-200 rounded-2xl shadow-sm space-y-6">
          <div className="flex justify-between items-center mb-2">
            <span className="font-bold text-slate-700">ترکیب رهن و اجاره</span>
            <span className="text-xs text-slate-400 bg-slate-100 px-2 py-1 rounded-full">قابل تنظیم</span>
          </div>

          {/* Slider */}
          <div className="relative pt-6 pb-2">
            <input
              type="range"
              min={0}
              max={totalValue}
              step={RAHN_UNIT} // 1 Million steps
              value={mortgagePart}
              onChange={handleSliderChange}
              className="w-full h-3 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
            />
            {/* Markers */}
            <div className="flex justify-between text-xs text-slate-400 mt-2">
              <span>تمام اجاره</span>
              <span>۵۰ - ۵۰</span>
              <span>رهن کامل</span>
            </div>
          </div>

          {/* Results Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-4 border-t border-slate-100">
            <div className="space-y-2">
              <label className="text-sm text-slate-500">مبلغ رهن</label>
              <div className="flex items-center justify-between bg-blue-50 p-3 rounded-lg border border-blue-100">
                <span className="font-mono font-bold text-xl text-blue-700">
                  {formatCurrency(mortgagePart)}
                </span>
                <span className="text-xs text-blue-400">تومان</span>
              </div>
              {/* Allow direct typing for mortgage part too */}
              <div className="pt-2">
                 <label className="text-xs text-slate-400 mb-1 block">تایپ مبلغ دقیق رهن:</label>
                 <CurrencyInput 
                    label="" 
                    value={mortgagePart} 
                    onChange={setMortgagePart} 
                    className="scale-90 origin-top-right -mr-[5%]" 
                 />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-sm text-slate-500">مبلغ اجاره ماهیانه</label>
              <div className="flex items-center justify-between bg-emerald-50 p-3 rounded-lg border border-emerald-100">
                <span className="font-mono font-bold text-xl text-emerald-700">
                  {formatCurrency(rentPart)}
                </span>
                <span className="text-xs text-emerald-400">تومان</span>
              </div>
               <div className="pt-2">
                  <p className="text-xs text-slate-400 leading-5">
                    این مبلغ اجاره معادل سود {formatCurrency(totalValue - mortgagePart)} تومان از پول رهن است.
                  </p>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BasicConversion;

import React, { useState, useEffect } from 'react';
import CurrencyInput from './CurrencyInput';
import { calculateTotalRahnValue, formatCurrency, rahnToRent, rentToRahn, RAHN_UNIT } from '../utils/currency';
import { ArrowLeftRight, TrendingUp } from 'lucide-react';

const RenewalCalculator: React.FC = () => {
  // Current Contract State
  const [curMortgage, setCurMortgage] = useState<number>(200000000);
  const [curRent, setCurRent] = useState<number>(3000000);

  // New Contract Logic
  // We track the "Target Total Value" for the new year.
  // Initially, it equals the current total value.
  const [increasePercent, setIncreasePercent] = useState<number>(20); // Default 20% increase
  const [newTotalValue, setNewTotalValue] = useState<number>(0);

  // The user can fix either Mortgage or Rent for the new contract
  // 'mortgage' means user typed a new mortgage, we calc rent
  // 'rent' means user typed a new rent, we calc mortgage
  const [lastEdited, setLastEdited] = useState<'mortgage' | 'rent'>('mortgage');
  const [newMortgage, setNewMortgage] = useState<number>(0);
  const [newRent, setNewRent] = useState<number>(0);

  // 1. Calculate Current Total Value
  const curTotalValue = calculateTotalRahnValue(curMortgage, curRent);

  // 2. Update New Total Value when Current Value or % changes
  useEffect(() => {
    const total = curTotalValue * (1 + increasePercent / 100);
    setNewTotalValue(total);
  }, [curTotalValue, increasePercent]);

  // 3. Re-balance New Mortgage/Rent when New Total Value changes
  // If Total Value changes (e.g. increase %), we usually keep the RATIO or keep one fixed?
  // Let's try to maintain the same Mortgage amount and put increase into Rent, or vice versa.
  // Strategy: Try to keep the `newMortgage` close to `curMortgage` initially, adjusting Rent.
  useEffect(() => {
    // Initial sync or update
    if (lastEdited === 'mortgage') {
        // If we were editing mortgage, keep mortgage, update rent based on NEW total
        let validMortgage = newMortgage;
        if (validMortgage === 0) validMortgage = curMortgage; // Default to current

        // Cap mortgage at total value
        if (validMortgage > newTotalValue) validMortgage = newTotalValue;

        setNewMortgage(validMortgage);
        const remaining = newTotalValue - validMortgage;
        setNewRent(rahnToRent(remaining));
    } else {
        // If we were editing rent
        let validRent = newRent;
        // Check bounds
        const maxRent = rahnToRent(newTotalValue);
        if (validRent > maxRent) validRent = maxRent;

        setNewRent(validRent);
        const remainingRahnEquivalent = rentToRahn(validRent);
        setNewMortgage(newTotalValue - remainingRahnEquivalent);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [newTotalValue]);

  // Handler for manually changing New Mortgage
  const handleNewMortgageChange = (val: number) => {
    setLastEdited('mortgage');
    let m = val;
    if (m > newTotalValue) m = newTotalValue;
    setNewMortgage(m);
    setNewRent(rahnToRent(newTotalValue - m));
  };

  // Handler for manually changing New Rent
  const handleNewRentChange = (val: number) => {
    setLastEdited('rent');
    let r = val;
    const maxRent = rahnToRent(newTotalValue);
    if (r > maxRent) r = maxRent;
    setNewRent(r);
    setNewMortgage(newTotalValue - rentToRahn(r));
  };

  return (
    <div className="space-y-8 animate-fade-in">
       <div className="bg-emerald-50 p-4 rounded-xl border border-emerald-100 flex items-start gap-3">
        <TrendingUp className="w-6 h-6 text-emerald-600 mt-1 flex-shrink-0" />
        <div>
          <h3 className="font-bold text-emerald-800 text-lg mb-1">محاسبه افزایش و تمدید</h3>
          <p className="text-emerald-600 text-sm leading-relaxed">
            مبالغ فعلی را وارد کنید، درصد افزایش سالیانه را تعیین کنید، و سپس با تغییر یکی از مقادیر جدید (رهن یا اجاره)، دیگری به صورت خودکار محاسبه می‌شود.
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Left Column: Current Status */}
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
          <h4 className="font-bold text-slate-700 border-b pb-2 mb-4">وضعیت فعلی (سال گذشته)</h4>
          <CurrencyInput
            label="مبلغ رهن فعلی"
            value={curMortgage}
            onChange={setCurMortgage}
          />
          <CurrencyInput
            label="مبلغ اجاره فعلی"
            value={curRent}
            onChange={setCurRent}
          />

          <div className="mt-6 p-4 bg-slate-50 rounded-xl">
             <div className="text-sm text-slate-500 mb-1">ارزش کل رهن (تبدیل شده):</div>
             <div className="text-xl font-mono font-bold text-slate-700">{formatCurrency(curTotalValue)} <span className="text-sm font-sans font-normal">تومان</span></div>
          </div>
        </div>

        {/* Right Column: New Contract */}
        <div className="bg-blue-50/50 p-6 rounded-2xl border border-blue-100 shadow-sm space-y-6 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-2 h-full bg-blue-500"></div>

          <div className="flex justify-between items-center border-b border-blue-200 pb-2">
            <h4 className="font-bold text-blue-900">قرارداد جدید</h4>
            <div className="flex items-center gap-2 bg-white px-2 py-1 rounded-lg border border-blue-200 shadow-sm">
                <span className="text-xs text-blue-800">درصد افزایش:</span>
                <input 
                    type="number" 
                    value={increasePercent}
                    onChange={(e) => setIncreasePercent(Number(e.target.value))}
                    className="w-12 text-center font-bold text-blue-600 outline-none border-b border-dashed border-blue-300 focus:border-blue-500"
                />
                <span className="text-xs text-blue-800">%</span>
            </div>
          </div>

          <div className="p-3 bg-blue-100 rounded-lg text-center">
             <div className="text-xs text-blue-800 mb-1">ارزش کل جدید (با {increasePercent}٪ افزایش):</div>
             <div className="text-xl font-mono font-bold text-blue-900">{formatCurrency(newTotalValue)} <span className="text-sm font-sans font-normal">تومان</span></div>
          </div>

          <div className="space-y-6 relative">
            <div className="absolute left-4 top-1/2 -translate-y-1/2 hidden md:block opacity-20">
                <ArrowLeftRight className="w-12 h-12 text-blue-900" />
            </div>

            <div className={`transition-all duration-300 p-2 rounded-lg ${lastEdited === 'mortgage' ? 'bg-white ring-2 ring-blue-400 shadow-md' : 'opacity-80'}`}>
                <CurrencyInput
                    label="رهن جدید (قابل ویرایش)"
                    value={newMortgage}
                    onChange={handleNewMortgageChange}
                />
            </div>

            <div className={`transition-all duration-300 p-2 rounded-lg ${lastEdited === 'rent' ? 'bg-white ring-2 ring-blue-400 shadow-md' : 'opacity-80'}`}>
                <CurrencyInput
                    label="اجاره جدید (قابل ویرایش)"
                    value={newRent}
                    onChange={handleNewRentChange}
                />
            </div>
          </div>

          <div className="text-xs text-blue-500 text-center mt-2">
            * با تغییر هر یک از مقادیر بالا، دیگری بر اساس ارزش کل جدید محاسبه می‌شود.
          </div>
        </div>
      </div>

      {/* Quick Diff Info */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 pt-4">
         <div className="bg-white p-3 rounded-xl border text-center">
            <div className="text-xs text-slate-400">تفاوت رهن</div>
            <div className={`font-mono font-bold text-lg ${newMortgage - curMortgage > 0 ? 'text-red-500' : 'text-green-500'}`} dir="ltr">
                {newMortgage - curMortgage > 0 ? '+' : ''}{formatCurrency(newMortgage - curMortgage)}
            </div>
         </div>
         <div className="bg-white p-3 rounded-xl border text-center">
            <div className="text-xs text-slate-400">تفاوت اجاره</div>
             <div className={`font-mono font-bold text-lg ${newRent - curRent > 0 ? 'text-red-500' : 'text-green-500'}`} dir="ltr">
                {newRent - curRent > 0 ? '+' : ''}{formatCurrency(newRent - curRent)}
            </div>
         </div>
      </div>
    </div>
  );
};

export default RenewalCalculator;

