import React, { createContext, useContext, useState, useEffect } from 'react';
import { translations, Language } from './translations';

interface AppContextType {
  lang: Language;
  setLang: (lang: Language) => void;
  theme: 'light' | 'dark';
  toggleTheme: () => void;
  t: typeof translations.fa;
  dir: 'rtl' | 'ltr';
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [lang, setLang] = useState<Language>('fa');
  const [theme, setTheme] = useState<'light' | 'dark'>('light');

  // Handle HTML dir and lang attributes
  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'fa' ? 'rtl' : 'ltr';
  }, [lang]);

  // Handle Dark Mode class
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const t = translations[lang];
  const dir = lang === 'fa' ? 'rtl' : 'ltr';

  return (
    <AppContext.Provider value={{ lang, setLang, theme, toggleTheme, t, dir }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
};

// Formats a number to string with commas (e.g., 1000000 -> 1,000,000)
export const formatCurrency = (value: number, lang: 'fa' | 'en' = 'fa'): string => {
  if (isNaN(value)) return '0';
  const locale = lang === 'fa' ? 'fa-IR' : 'en-US';
  return new Intl.NumberFormat(locale).format(value);
};

// Parses a string with commas back to a number (e.g., "1,000,000" -> 1000000)
// Handles English, Persian, and Arabic digits.
export const parseCurrency = (value: string): number => {
  if (!value) return 0;

  // Convert Persian and Arabic digits to English digits
  const englishValue = value
    .replace(/[۰٠]/g, '0')
    .replace(/[۱١]/g, '1')
    .replace(/[۲٢]/g, '2')
    .replace(/[۳٣]/g, '3')
    .replace(/[۴٤]/g, '4')
    .replace(/[۵٥]/g, '5')
    .replace(/[۶٦]/g, '6')
    .replace(/[۷٧]/g, '7')
    .replace(/[۸٨]/g, '8')
    .replace(/[۹٩]/g, '9');

  // Remove non-numeric characters (commas, spaces, etc)
  const cleanValue = englishValue.replace(/[^0-9]/g, '');

  const num = parseInt(cleanValue, 10);
  return isNaN(num) ? 0 : num;
};

// Conversion Constants
// 1 Million Rahn = 30,000 Rent
export const RAHN_TO_RENT_RATE = 30000; 
export const RAHN_UNIT = 1000000;

// Converts Rahn to equivalent Rent
export const rahnToRent = (rahn: number): number => {
  return (rahn / RAHN_UNIT) * RAHN_TO_RENT_RATE;
};

// Converts Rent to equivalent Rahn
export const rentToRahn = (rent: number): number => {
  return (rent / RAHN_TO_RENT_RATE) * RAHN_UNIT;
};

// Calculates total value of a deal in terms of "Full Rahn"
export const calculateTotalRahnValue = (rahn: number, rent: number): number => {
  return rahn + rentToRahn(rent);
};

import React from 'react';
import { formatCurrency, parseCurrency } from '../utils/currency';
import { useApp } from '../utils/context';

interface CurrencyInputProps {
  label: string;
  value: number | ''; // Allow empty string for "unfilled" state
  onChange: (value: number | '') => void; // Update type
  placeholder?: string;
  className?: string;
  disabled?: boolean;
}

const CurrencyInput: React.FC<CurrencyInputProps> = ({ 
  label, 
  value, 
  onChange, 
  placeholder,
  className = "",
  disabled = false
}) => {
  const { lang, t } = useApp();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value;

    // Check if input is empty
    if (!rawValue) {
      onChange('');
      return;
    }

    const numValue = parseCurrency(rawValue);
    onChange(numValue);
  };

  const displayValue = value === '' || value === 0 ? '' : formatCurrency(value, lang);

  return (
    <div className={`flex flex-col gap-1 ${className}`}>
      {label && <label className="text-sm font-medium text-slate-600 dark:text-slate-400">{label}</label>}
      <div className="relative">
        <input
          type="text"
          inputMode="numeric"
          dir="ltr"
          value={displayValue}
          onChange={handleChange}
          disabled={disabled}
          placeholder={placeholder || t.placeholderAmount}
          className={`w-full p-3 pl-12 border rounded-lg outline-none transition-all text-left font-mono text-lg
            focus:ring-2 focus:ring-blue-500 focus:border-blue-500 dark:focus:ring-blue-400
            ${disabled 
              ? 'bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700' 
              : 'bg-white dark:bg-slate-800 border-slate-300 dark:border-slate-600 text-slate-800 dark:text-white'
            }
            placeholder:text-slate-400 dark:placeholder:text-slate-500
            `}
        />
        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-500 text-sm pointer-events-none">
          {t.currency}
        </span>
      </div>
    </div>
  );
};

